{
  "pou_name": "fixture_motor_start_stop",
  "pou_type": "FUNCTION_BLOCK",
  "declaration": "FUNCTION_BLOCK fixture_motor_start_stop
VAR_INPUT
    StartBtn : BOOL;
    StopBtn : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    MotorLatch : BOOL;
END_VAR",
  "implementation": "IF EStop OR StopBtn THEN
    MotorLatch := FALSE;
ELSIF StartBtn THEN
    MotorLatch := TRUE;
END_IF;
Motor := MotorLatch;"
}
